// loadReporterStubShardLoadArgs returns the samples of the arguments of
// ShardLoad.
func loadReporterStubShardLoadArgs(tb assert.TB) shard.ID {
	tb.Helper()
	var a0 shard.ID
	return a0
}

// loadReporterStubShardLoad calls ShardLoad of s with the samples of its
// arguments.
func loadReporterStubShardLoad(tb assert.TB, s *drivertest.LoadReporterStub) shard.Load {
	tb.Helper()
	a0 := loadReporterStubShardLoadArgs(tb)
	return s.ShardLoad(a0)
}

// loadReporterStubShardLoadPins returns the samples of the results of
// ShardLoad.
func loadReporterStubShardLoadPins() shard.Load {
	var want0 shard.Load
	want0 = shard.Load{"ShardLoad-a": 1.5}
	return want0
}

// loadReporterStubShardLoadSubject returns the subject of [stub.Behaviour]
// for ShardLoad. The subject calls a new double that reports to tb.
func loadReporterStubShardLoadSubject(
	tb assert.TB,
) stub.Subject[drivertest.LoadReporterShardLoadCall, drivertest.LoadReporterShardLoadReturn] {
	tb.Helper()
	s := drivertest.NewLoadReporterStub(tb)
	return stub.Subject[drivertest.LoadReporterShardLoadCall, drivertest.LoadReporterShardLoadReturn]{
		Stub: s.OnShardLoad.MethodStub,
		Call: func() {
			_ = loadReporterStubShardLoad(tb, s)
		},
		Result: func() drivertest.LoadReporterShardLoadReturn {
			got0 := loadReporterStubShardLoad(tb, s)
			return drivertest.LoadReporterShardLoadReturn{Result: got0}
		},
		Override: func(mark func()) {
			s.OnShardLoad.Func(func(_ shard.ID) shard.Load {
				mark()
				var z0 shard.Load
				return z0
			})
		},
	}
}

// loadReporterStubInstance is the instance of a
// drivertest.LoadReporterStub that the checks of the constructors and the
// options drive.
type loadReporterStubInstance = stub.Instance[drivertest.LoadReporterShardLoadCall]

// loadReporterStubInstanceOf returns the instance of s. The options apply
// to the whole double, so the checks call ShardLoad alone.
func loadReporterStubInstanceOf(tb assert.TB, s *drivertest.LoadReporterStub) loadReporterStubInstance {
	tb.Helper()
	return loadReporterStubInstance{
		Stub: s.OnShardLoad.MethodStub,
		Call: func() {
			_ = loadReporterStubShardLoad(tb, s)
		},
		Reset: s.ResetCalls,
	}
}

